UPDATE category SET active = false, public_visible = false, launch_phase = CASE WHEN title IN ('Строительство', 'Сиделка') THEN 'PHASE_2' ELSE 'PROHIBITED_FOR_MVP' END, updated_at = CURRENT_TIMESTAMP;
UPDATE category SET title = 'Ремонт и отделка', slug = 'repair-finishing' WHERE id = 1; UPDATE category SET title = 'Клининг', slug = 'cleaning' WHERE id = 3; UPDATE category SET title = 'Грузоперевозки', slug = 'freight-transport' WHERE id = 4; UPDATE category SET title = 'Курьерские услуги', slug = 'courier-services' WHERE id = 5; UPDATE category SET title = 'Обучение', slug = 'education' WHERE id = 7; UPDATE category SET title = 'Дизайн', slug = 'design' WHERE id = 8; UPDATE category SET title = 'IT и разработка', slug = 'it-development' WHERE id = 9; UPDATE category SET title = 'Фото и видео', slug = 'photo-video' WHERE id = 11;
CREATE TEMP TABLE mvp_category_seed ( seq INT PRIMARY KEY, parent_slug VARCHAR(120), title VARCHAR(255) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, sort_order INT NOT NULL ) ON COMMIT DROP;
