INSERT INTO category ( public_id, title, parent_id, weight, slug, icon, risk_level, service_mode, launch_phase, active, public_visible, sort_order, requires_verification_level, requires_manual_approval, requires_license, allows_remote, allows_onsite, allows_escrow, allows_cash, allows_milestones, allows_attachments, allows_contact_reveal, created_at, updated_at, version ) SELECT '06CAT' || LPAD(seed.seq::text, 21, '0'), seed.title, NULL, seed.sort_order, seed.slug, NULL, 'LOW', 'HYBRID', 'MVP', true, true, seed.sort_order, 'NONE', false, false, true, true, true, true, false, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0 FROM mvp_category_seed seed WHERE seed.parent_slug IS NULL ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, active = true, public_visible = true, launch_phase = 'MVP', sort_order = EXCLUDED.sort_order, weight = EXCLUDED.weight, updated_at = CURRENT_TIMESTAMP;
INSERT INTO category ( public_id, title, parent_id, weight, slug, icon, risk_level, service_mode, launch_phase, active, public_visible, sort_order, requires_verification_level, requires_manual_approval, requires_license, allows_remote, allows_onsite, allows_escrow, allows_cash, allows_milestones, allows_attachments, allows_contact_reveal, created_at, updated_at, version ) SELECT '06CAT' || LPAD(seed.seq::text, 21, '0'), seed.title, parent.id, seed.sort_order, seed.slug, NULL, 'LOW', 'HYBRID', 'MVP', true, true, seed.sort_order, 'NONE', false, false, true, true, true, true, false, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0 FROM mvp_category_seed seed JOIN category parent ON parent.slug = seed.parent_slug WHERE seed.parent_slug IS NOT NULL ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, parent_id = EXCLUDED.parent_id, active = true, public_visible = true, launch_phase = 'MVP', sort_order = EXCLUDED.sort_order, weight = EXCLUDED.weight, updated_at = CURRENT_TIMESTAMP;
UPDATE category category SET risk_level = CASE WHEN root.slug IN ('design', 'online-work', 'it-development') THEN 'LOW' WHEN root.slug IN ('repair-finishing', 'auto-services') THEN 'HIGH' ELSE 'MEDIUM' END, service_mode = CASE WHEN root.slug IN ('online-work', 'it-development') THEN 'REMOTE' WHEN root.slug IN ('design', 'marketing-advertising', 'photo-video', 'education') THEN 'HYBRID' ELSE 'ONSITE' END, requires_verification_level = CASE WHEN root.slug IN ('design', 'online-work', 'it-development') THEN 'NONE' WHEN root.slug IN ('repair-finishing', 'auto-services') THEN 'ID_VERIFIED' ELSE 'PHONE_VERIFIED' END, allows_remote = root.slug IN ('design', 'online-work', 'it-development', 'marketing-advertising', 'photo-video', 'education'), allows_onsite = root.slug NOT IN ('online-work', 'it-development'), allows_escrow = true, allows_cash = true, allows_milestones = root.slug IN ('repair-finishing', 'design', 'it-development'), allows_attachments = true, active = true, public_visible = true, launch_phase = 'MVP', updated_at = CURRENT_TIMESTAMP FROM mvp_category_seed seed JOIN category seeded ON seeded.slug = seed.slug JOIN category root ON root.id = COALESCE(seeded.parent_id, seeded.id) WHERE category.id = seeded.id;
UPDATE category SET risk_level = 'HIGH', requires_verification_level = 'ID_VERIFIED' WHERE slug IN ('electrician', 'demolition', 'aerial-photography');
INSERT INTO category_translation (category_id, locale, name, description, created_at, updated_at) SELECT category.id, locale.locale, seed.title, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM mvp_category_seed seed JOIN category ON category.slug = seed.slug CROSS JOIN (VALUES ('ru'), ('kk')) locale(locale) ON CONFLICT (category_id, locale) DO UPDATE SET name = EXCLUDED.name, updated_at = CURRENT_TIMESTAMP;
SELECT setval( pg_get_serial_sequence('category', 'id'), COALESCE((SELECT MAX(id) FROM category), 1), true );
